import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        // balance = unmatched '('; missing = ')' that had nothing to match.
        long balance = 0, missing = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') balance++;
            else if (balance > 0) balance--;
            else missing++;
        }
        System.out.println(missing + balance);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	var s string
	fmt.Fscan(bufio.NewReader(os.Stdin), &s)
	// balance = unmatched '('; missing = ')' that had nothing to match.
	balance, missing := 0, 0
	for _, c := range s {
		if c == '(' {
			balance++
		} else if balance > 0 {
			balance--
		} else {
			missing++
		}
	}
	fmt.Println(missing + balance)
}
